flag.source:
declare const load: (assign: (value: number) => void) => void;
let total!: number;
load((value) => {
  total = value;
});
export { total };

allow.source:
declare const ready: boolean;
export const waiting = !ready;
export const differs = (left: number, right: number): boolean => left !== right;

let total: number = 0;
export class Account {
  balance: number = total;
}
export { total };
